from collections import defaultdict

def schedule_tasks(tasks):
    # Create a graph to represent dependencies and their durations
    graph = defaultdict(list)
    duration = {}

    for name, d, deps in tasks:
        duration[name] = d
        for dep in deps:
            graph[dep].append(name)

    # Initialize the start times of all tasks
    start_times = {name: 0 for name in graph}

    # Perform a topological sort to determine the order of tasks
    def dfs(node):
        if node not in start_times:
            start_times[node] = max(start_times[dep] for dep in graph[node]) + duration[node]
            for neighbor in graph[node]:
                dfs(neighbor)

    for task in graph:
        dfs(task)

    # Return the list of tasks sorted by start time and name
    return [(name, start_time, start_time + duration[name]) for name, start_time in start_times.items()]
