def schedule_tasks(tasks):
    from collections import defaultdict, deque

    task_map = {task[0]: (task[1], set(task[2])) for task in tasks}
    graph = defaultdict(list)
    in_degree = defaultdict(int)

    for name, _, dependencies in tasks:
        for dependency in dependencies:
            graph[dependency].append(name)
            in_degree[name] += 1

    queue = deque([name for name, degree in in_degree.items() if degree == 0])
    schedule = []

    while queue:
        current_task = queue.popleft()
        start_time = max(schedule[-1][2] if schedule else 0, sum(task_map[dep][0] for dep in graph[current_task]))
        end_time = start_time + task_map[current_task][0]
        schedule.append((current_task, start_time, end_time))

        for neighbor in graph[current_task]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    return sorted(schedule, key=lambda x: (x[1], x[0]))
